        content:
            `<p>本该是高中女生的「我」居然在不知不觉间来到未知之地，还转生成「蜘蛛」怪物了！？</p>
<p>虽然我成功逃离喜欢同类相食的蜘蛛父母，却不小心闯进怪物们的巢穴。</p>
<p>在这个毒蛙、大蛇、巨猿还有龙四处横行的可怕迷宫里，</p>
<p>只是一只小蜘蛛的「我」有办法存活吗……</p>
<p>真是……开玩笑也该有个限度吧！</p>
<p>造成这种状况的元凶快给我出来——！</p>
<p>在各方网友的热烈声援之下，蜘蛛子的生存战略正式展开！</p>`
