            `<div class="mt45">

<p>有一个勇者和魔王之间的战斗反复上演的世界。</p>
<p>在这场战斗中使出的时空大魔法，在日本某间高中的教室里爆发。</p>
<p>教室里的所有人都被魔法直接击中，轻而易举就被夺去生命。</p>
<p>他们的灵魂散落在异世界中，分别转生为全新的生命。</p>

  </div>`
